import re

SCHEMA = {
    'username': {'type': 'str', 'required': True, 'min_len': 3, 'max_len': 20},
    'age': {'type': 'int', 'required': True, 'min': 0, 'max': 150},
    'email': {'type': 'str', 'required': False, 'pattern': r'^[^@]+@[^@]+\.[a-z]{2,}$'},
    'tags': {'type': 'list', 'required': False, 'max_items': 5},
}


def validate_body(data, schema):
    cleaned = {}
    errors = []
    source = data if isinstance(data, dict) else {}
    for field, rule in schema.items():
        if field not in source or source[field] is None:
            if rule.get('required'):
                errors.append({'field': field, 'message': '缺少必填字段'})
            continue
        value = source[field]
        kind = rule.get('type')
        if kind == 'int' and isinstance(value, str) and value.strip().lstrip('-').isdigit():
            value = int(value)
        if kind == 'str' and isinstance(value, (int, float)) and not isinstance(value, bool):
            value = str(value)
        ok = True
        if kind == 'int' and (not isinstance(value, int) or isinstance(value, bool)):
            errors.append({'field': field, 'message': '必须是 int 类型'})
            ok = False
        elif kind == 'str' and not isinstance(value, str):
            errors.append({'field': field, 'message': '必须是 str 类型'})
            ok = False
        elif kind == 'list' and not isinstance(value, list):
            errors.append({'field': field, 'message': '必须是 list 类型'})
            ok = False
        if not ok:
            continue
        if 'min_len' in rule and isinstance(value, str) and len(value) < rule['min_len']:
            errors.append({'field': field, 'message': f'长度不能少于 {rule["min_len"]}'})
            ok = False
        elif 'max_len' in rule and isinstance(value, str) and len(value) > rule['max_len']:
            errors.append({'field': field, 'message': f'长度不能超过 {rule["max_len"]}'})
            ok = False
        if ok and 'min' in rule and isinstance(value, int) and value < rule['min']:
            errors.append({'field': field, 'message': f'不能小于 {rule["min"]}'})
            ok = False
        if ok and 'max' in rule and isinstance(value, int) and value > rule['max']:
            errors.append({'field': field, 'message': f'不能大于 {rule["max"]}'})
            ok = False
        if ok and 'pattern' in rule and isinstance(value, str) and not re.match(rule['pattern'], value):
            errors.append({'field': field, 'message': '格式不正确'})
            ok = False
        if ok and 'max_items' in rule and isinstance(value, list) and len(value) > rule['max_items']:
            errors.append({'field': field, 'message': f'最多 {rule["max_items"]} 项'})
            ok = False
        if ok:
            cleaned[field] = value
    return cleaned, errors


print(validate_body({'username': 'lilei', 'age': '18', 'email': 'a@b.com', 'tags': ['x']}, SCHEMA))
print(validate_body({'username': 'ab', 'age': 200}, SCHEMA))
print(validate_body({}, SCHEMA))
